from __future__ import annotations

import os
from pathlib import Path

from rasa.core.channels.voice_stream.call_recording.recording_encoder import (
    RECORDING_CONTENT_TYPE,
)
from rasa.core.channels.voice_stream.call_recording.storages.base import (
    RecordingReference,
    _object_key,
)
from rasa.core.config.available_endpoints import RecordingConfig
from rasa.core.persistor import AWSPersistor
from rasa.env import AWS_ENDPOINT_URL_ENV


class S3RecordingStorage:
    """Minimal S3 recording storage wrapper backed by the model persistor."""

    def __init__(self, config: RecordingConfig) -> None:
        if config.s3 is None:
            raise ValueError("S3 recording storage requires recordings.s3 config.")
        self._s3_config = config.s3
        endpoint_url = self._s3_config.endpoint_url or os.environ.get(
            AWS_ENDPOINT_URL_ENV
        )
        self._persistor = AWSPersistor(
            bucket_name=self._s3_config.bucket,
            endpoint_url=endpoint_url,
            region_name=self._s3_config.region,
        )

    def upload(
        self, source: Path, conversation_id: str, call_id: str
    ) -> RecordingReference:
        """Upload the recording to S3 and return its object location.

        Args:
            source: Path to the encoded recording file.
            conversation_id: Conversation identifier used in the object key.
            call_id: Call identifier used in the object key.

        Returns:
            Location of the uploaded recording.
        """
        key = _object_key(self._s3_config.prefix, conversation_id, call_id)
        self._persistor.persist_file(
            file_key=key,
            file_path=str(source),
            content_type=RECORDING_CONTENT_TYPE,
        )
        return RecordingReference(
            provider="s3",
            bucket=self._s3_config.bucket,
            key=key,
            uri=f"s3://{self._s3_config.bucket}/{key}",
            content_type=RECORDING_CONTENT_TYPE,
        )
